const upsertTokenLease = `-- name: UpsertTokenLease :exec
INSERT INTO token_leases (
  token, masked_token, client_name, source_ip, egress_id, seen_at, expires_at
)
VALUES (?, ?, ?, ?, ?, ?, ?)
ON CONFLICT(token) DO UPDATE SET
  masked_token = excluded.masked_token,
  client_name = excluded.client_name,
  source_ip = excluded.source_ip,
  egress_id = excluded.egress_id,
  seen_at = excluded.seen_at,
  expires_at = excluded.expires_at
`

type UpsertTokenLeaseParams struct {
	Token       string         `json:"token"`
	MaskedToken string         `json:"masked_token"`
	ClientName  string         `json:"client_name"`
	SourceIp    string         `json:"source_ip"`
	EgressID    string         `json:"egress_id"`
	SeenAt      string         `json:"seen_at"`
	ExpiresAt   sql.NullString `json:"expires_at"`
}

func (q *Queries) UpsertTokenLease(ctx context.Context, arg UpsertTokenLeaseParams) error {
	_, err := q.db.ExecContext(ctx, upsertTokenLease,
		arg.Token,
		arg.MaskedToken,
		arg.ClientName,
		arg.SourceIp,
		arg.EgressID,
		arg.SeenAt,
		arg.ExpiresAt,
	)
	return err
}
